mermaid:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	retrieve(retrieve)
	propose(propose)
	verify(verify)
	propose_fallback(propose_fallback)
	finalize(finalize)
	__end__([<p>__end__</p>]):::last
	__start__ --> retrieve;
	propose --> verify;
	propose_fallback --> verify;
	retrieve --> propose;
	verify -. &nbsp;done&nbsp; .-> finalize;
	verify -. &nbsp;retry&nbsp; .-> propose_fallback;
	finalize --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
